from pathlib import Path

schedule_path = Path("server/jobs/sync-nfl-schedule.ts")
schedule = schedule_path.read_text()
start = schedule.index("async function loadFullSeason(")
end = schedule.index("async function persistGame", start)
new_loader = '''async function loadFullSeason(\n  season: number,\n  result: NflScheduleSyncResult,\n): Promise<EspnNflGame[]> {\n  const games = new Map<string, EspnNflGame>();\n  const weekCounts: Record<NflSeasonType, number> = { preseason: 5, regular: 18, postseason: 6 };\n  const calendarYears = [season, season + 1];\n\n  for (const seasonType of ["preseason", "regular", "postseason"] as const) {\n    let seasonTypeGames = 0;\n\n    // ESPN's dates=YYYY filter is a calendar-year filter, not an NFL-season filter.\n    // Every NFL season crosses into the following January/February, so query both\n    // calendar years and retain only events whose ESPN season metadata matches.\n    for (const calendarYear of calendarYears) {\n      try {\n        const values = await espnNfl.getGames({\n          dates: String(calendarYear),\n          seasonType,\n          limit: 1000,\n        });\n        result.requestCount++;\n        for (const game of values) {\n          if (game.season !== season || game.seasonType !== seasonType) continue;\n          if (!games.has(game.espnId)) seasonTypeGames++;\n          games.set(game.espnId, game);\n        }\n      } catch (error: any) {\n        result.errors.push(\n          `${season} ${seasonType} calendar ${calendarYear}: ${error?.message || error}`,\n        );\n      }\n    }\n\n    if (seasonTypeGames > 0) continue;\n\n    // Fallback for provider shape/regression changes. Keep both calendar years here\n    // too so Week 18 and postseason cannot silently disappear again.\n    for (let week = 1; week <= weekCounts[seasonType]; week++) {\n      for (const calendarYear of calendarYears) {\n        try {\n          const values = await espnNfl.getGames({\n            dates: String(calendarYear),\n            seasonType,\n            week,\n            limit: 100,\n          });\n          result.requestCount++;\n          for (const game of values) {\n            if (game.season === season && game.seasonType === seasonType) {\n              games.set(game.espnId, game);\n            }\n          }\n        } catch (error: any) {\n          result.errors.push(\n            `${season} ${seasonType} week ${week} calendar ${calendarYear}: ${error?.message || error}`,\n          );\n        }\n      }\n    }\n  }\n  return [...games.values()];\n}\n\n'''
schedule_path.write_text(schedule[:start] + new_loader + schedule[end:])

repair_path = Path("scripts/nfl-history-repair.ts")
repair_path.write_text('''import "dotenv/config";\nimport { pool } from "../server/db";\nimport { syncNFLSchedule } from "../server/jobs/sync-nfl-schedule";\nimport { syncNflverseStats } from "../server/jobs/sync-nflverse-stats";\n\nconst REPAIR_ID = "nfl_history_calendar_boundary_repair_v2";\nconst LOCK_NAME = "sportfolio:nfl:history-calendar-boundary-repair-v2";\nconst HISTORICAL_SEASONS = [2024, 2025] as const;\n\ntype CoverageKey = `${number}:${string}`;\n\nasync function main() {\n  if (\n    process.env.NODE_ENV !== "production" &&\n    process.env.NFL_MIGRATION_ALLOW_NON_PROD !== "true"\n  ) {\n    throw new Error(\n      "nfl:repair-history is production-only unless NFL_MIGRATION_ALLOW_NON_PROD=true",\n    );\n  }\n\n  const client = await pool.connect();\n  let locked = false;\n  try {\n    await client.query("SELECT pg_advisory_lock(hashtext($1))", [LOCK_NAME]);\n    locked = true;\n    await client.query(`\n      CREATE TABLE IF NOT EXISTS sportfolio_operational_migrations (\n        id text PRIMARY KEY,\n        completed_at timestamptz NOT NULL DEFAULT now(),\n        details jsonb NOT NULL DEFAULT '{}'::jsonb\n      )\n    `);\n    const marker = await client.query(\n      "SELECT 1 FROM sportfolio_operational_migrations WHERE id=$1",\n      [REPAIR_ID],\n    );\n    if (marker.rowCount) {\n      console.log(`[nfl_history_repair] ${REPAIR_ID} already completed; no-op`);\n      return;\n    }\n\n    const schedules = [];\n    for (const season of HISTORICAL_SEASONS) {\n      const schedule = await syncNFLSchedule({ season, fullSeason: true });\n      schedules.push({ season, ...schedule });\n      console.log(`[nfl_history_repair] schedule ${season} ${JSON.stringify(schedule)}`);\n      if (schedule.errors.length !== 0) {\n        throw new Error(`NFL ${season} schedule repair failed: ${JSON.stringify(schedule)}`);\n      }\n    }\n\n    const coverageRows = await client.query<{ season: number; season_type: string; games: number }>(\n      `\n        SELECT season, season_type, count(*)::int AS games\n        FROM daily_games\n        WHERE sport = 'NFL' AND season = ANY($1::int[])\n        GROUP BY season, season_type\n        ORDER BY season, season_type\n      `,\n      [[...HISTORICAL_SEASONS]],\n    );\n    const coverage = new Map<CoverageKey, number>(\n      coverageRows.rows.map((row) => [\n        `${Number(row.season)}:${String(row.season_type)}` as CoverageKey,\n        Number(row.games),\n      ]),\n    );\n    for (const season of HISTORICAL_SEASONS) {\n      const regular = coverage.get(`${season}:regular`) || 0;\n      const postseason = coverage.get(`${season}:postseason`) || 0;\n      if (regular !== 272 || postseason !== 13) {\n        throw new Error(\n          `NFL ${season} schedule coverage invalid: regular=${regular}, postseason=${postseason}`,\n        );\n      }\n    }\n    console.log(`[nfl_history_repair] coverage ${JSON.stringify(coverageRows.rows)}`);\n\n    const result = await syncNflverseStats({ years: [...HISTORICAL_SEASONS] });\n    console.log(`[nfl_history_repair] stats ${JSON.stringify(result)}`);\n    if (result.errorCount !== 0 || result.recordsProcessed === 0 || result.gamesMissing !== 0) {\n      throw new Error(`NFL history repair verification failed: ${JSON.stringify(result)}`);\n    }\n\n    const verification = await client.query<{ stats: number; orphan_stats: number }>(`\n      SELECT\n        count(*) FILTER (WHERE s.sport = 'NFL' AND s.season IN ('2024', '2025'))::int AS stats,\n        count(*) FILTER (\n          WHERE s.sport = 'NFL'\n            AND s.season IN ('2024', '2025')\n            AND g.game_id IS NULL\n        )::int AS orphan_stats\n      FROM player_game_stats s\n      LEFT JOIN daily_games g ON g.game_id = s.game_id\n    `);\n    const verificationRow = verification.rows[0] || { stats: 0, orphan_stats: 0 };\n    if (Number(verificationRow.stats) === 0 || Number(verificationRow.orphan_stats) !== 0) {\n      throw new Error(`NFL history DB verification failed: ${JSON.stringify(verificationRow)}`);\n    }\n    console.log(`[nfl_history_repair] verification ${JSON.stringify(verificationRow)}`);\n\n    await client.query(\n      "INSERT INTO sportfolio_operational_migrations(id, details) VALUES ($1, $2::jsonb)",\n      [\n        REPAIR_ID,\n        JSON.stringify({ schedules, coverage: coverageRows.rows, stats: result, verification: verificationRow }),\n      ],\n    );\n    console.log(`[nfl_history_repair] ${REPAIR_ID} completed successfully`);\n  } finally {\n    if (locked) {\n      try {\n        await client.query("SELECT pg_advisory_unlock(hashtext($1))", [LOCK_NAME]);\n      } catch (error) {\n        console.warn("[nfl_history_repair] advisory unlock failed", error);\n      }\n    }\n    client.release();\n    await pool.end();\n  }\n}\n\nmain().catch((error) => {\n  console.error("[nfl_history_repair] failed", error);\n  process.exitCode = 1;\n});\n''')

test_path = Path("server/jobs/sync-nfl-schedule.test.ts")
test_path.write_text('''import { beforeEach, describe, expect, it, vi } from "vitest";\n\nvi.mock("../storage", () => ({\n  storage: {\n    getDailyGameByGameId: vi.fn(),\n    createDailyGame: vi.fn(),\n    updateDailyGame: vi.fn(),\n  },\n}));\n\nimport { storage } from "../storage";\nimport { espnNfl, type EspnNflGame } from "../nfl/espn-client";\nimport { syncNFLSchedule } from "./sync-nfl-schedule";\n\nfunction game(input: {\n  id: string;\n  seasonType: "preseason" | "regular" | "postseason";\n  week: number;\n  startsAt: string;\n  home?: string;\n  away?: string;\n}): EspnNflGame {\n  return {\n    espnId: input.id,\n    season: 2024,\n    seasonType: input.seasonType,\n    week: input.week,\n    startsAt: new Date(input.startsAt),\n    status: "completed",\n    sourceStatus: "STATUS_FINAL",\n    homeTeam: input.home || "KC",\n    awayTeam: input.away || "BUF",\n    homeScore: 24,\n    awayScore: 20,\n    venue: "Example Stadium",\n    period: 4,\n    clock: "0:00",\n  };\n}\n\ndescribe("NFL full-season schedule sync", () => {\n  beforeEach(() => {\n    vi.restoreAllMocks();\n    vi.mocked(storage.getDailyGameByGameId).mockReset().mockResolvedValue(undefined as never);\n    vi.mocked(storage.createDailyGame).mockReset().mockResolvedValue(undefined as never);\n    vi.mocked(storage.updateDailyGame).mockReset().mockResolvedValue(undefined as never);\n  });\n\n  it("loads Week 18 and postseason from the following calendar year", async () => {\n    const preseason = game({\n      id: "pre",\n      seasonType: "preseason",\n      week: 1,\n      startsAt: "2024-08-01T00:00:00Z",\n    });\n    const week18 = game({\n      id: "week18",\n      seasonType: "regular",\n      week: 18,\n      startsAt: "2025-01-05T18:00:00Z",\n      home: "NYJ",\n      away: "MIA",\n    });\n    const wildCard = game({\n      id: "wildcard",\n      seasonType: "postseason",\n      week: 1,\n      startsAt: "2025-01-12T18:00:00Z",\n      home: "BUF",\n      away: "DEN",\n    });\n\n    const getGames = vi.spyOn(espnNfl, "getGames").mockImplementation(async (options = {}) => {\n      if (options.dates === "2024" && options.seasonType === "preseason") return [preseason];\n      if (options.dates === "2025" && options.seasonType === "regular") return [week18];\n      if (options.dates === "2025" && options.seasonType === "postseason") return [wildCard];\n      return [];\n    });\n\n    const result = await syncNFLSchedule({ season: 2024, fullSeason: true });\n\n    expect(result.errors).toEqual([]);\n    expect(result.requestCount).toBe(6);\n    expect(result.gamesProcessed).toBe(3);\n    expect(getGames).toHaveBeenCalledWith(\n      expect.objectContaining({ dates: "2025", seasonType: "regular", limit: 1000 }),\n    );\n    expect(getGames).toHaveBeenCalledWith(\n      expect.objectContaining({ dates: "2025", seasonType: "postseason", limit: 1000 }),\n    );\n    expect(storage.createDailyGame).toHaveBeenCalledWith(\n      expect.objectContaining({ gameId: "nfl_week18", season: 2024, seasonType: "regular", week: 18 }),\n    );\n    expect(storage.createDailyGame).toHaveBeenCalledWith(\n      expect.objectContaining({\n        gameId: "nfl_wildcard",\n        season: 2024,\n        seasonType: "postseason",\n        week: 1,\n      }),\n    );\n  });\n});\n''')
